function test(name,fn){try{fn();console.log('PASS '+name);passed++;}catch(e){console.error('FAIL '+name+': '+e.message);failed++;}}
function setup(id='basics'){const e=env();assert.ok(e.c.JPWLearningGuide,'guide API missing');e.add('#dash');e.add('#brandHomeBtn');e.c.JPWLearningGuide.start(id);e.flush();return e;}
test('catalog and controller exist',()=>{const e=env();assert.ok(e.c.JPWLearningCatalog,'catalog missing');assert.ok(e.c.JPWLearningGuide,'guide missing');});
test('catalog is immutable and all IDs/copy/required tracks are complete',()=>{const c=env().c.JPWLearningCatalog;assert.ok(c);assert.equal(Object.isFrozen(c),true);assert.deepEqual(Array.from(c.tracks,t=>t.id),['basics','personal-finance','forex','research','management','tools','alladin','general','planning']);const ids=new Set();for(const t of c.tracks){assert.ok(t.steps.length>=2);for(const s of t.steps){assert.ok(s.id.startsWith(t.id+'-')||t.id==='management'&&['forex-accounting','forex-reserves'].includes(s.id));assert.ok(!ids.has(s.id));ids.add(s.id);for(const key of ['title','objective','instruction','expected'])assert.ok(s[key]?.length>15,s.id+' '+key);}}});
test('Dante journey starts only by explicit choice and saves original lesson ownership',()=>{const e=env();assert.equal(e.writes(),0);assert.equal(e.c.JPWLearningGuide.snapshot().progress.mode,'journey');e.add('#dash');e.c.JPWLearningGuide.startJourney();e.flush();assert.equal(e.c.JPWLearningGuide.snapshot().mode,'journey');assert.equal(e.c.JPWLearningGuide.snapshot().trackId,'basics');assert.equal(e.c.JPWLearningGuide.snapshot().stepId,'basics-home');e.c.JPWLearningGuide.startJourney({stepId:'forex-planning'});e.flush();assert.equal(e.c.JPWLearningGuide.snapshot().trackId,'forex');assert.equal(e.c.JPWLearningGuide.snapshot().mode,'journey');assert.equal(e.c.JPWLearningGuide.startJourney({stepId:'invalid'}),false);});
test('Dante journey crosses chapter boundaries with one bookmark and no automatic credit',()=>{const e=env();e.add('#dash');const c=e.c.JPWLearningCatalog,last=c.journey[0].stepIds.at(-1),next=c.journey[1].stepIds[0];e.c.JPWLearningGuide.startJourney({stepId:last});e.flush();e.c.cb.skip();e.flush();assert.equal(e.c.JPWLearningGuide.snapshot().stepId,next);assert.equal(e.c.JPWLearningGuide.snapshot().progress.steps[next],undefined);assert.equal(e.c.JPWLearningGuide.snapshot().progress.steps[last].orientation,'skipped');});
test('Dante unavailable chapters remain traversable without marking seen or skipped',()=>{const e=env();const c=e.c.JPWLearningCatalog,chapter=c.journey.find(x=>x.id==='alladin');e.c.JPWLearningGuide.startJourney({stepId:chapter.stepIds[0]});e.flush();assert.equal(e.c.JPWLearningGuide.snapshot().paused,false);assert.equal(e.c.model.unavailable,true);e.c.cb.understand();assert.equal(e.c.JPWLearningGuide.snapshot().progress.steps[chapter.stepIds[0]],undefined);e.c.cb.next();e.flush();assert.equal(e.c.JPWLearningGuide.snapshot().stepId,c.journey.find(x=>x.id==='general').stepIds[0]);assert.equal(Object.keys(e.c.JPWLearningGuide.snapshot().progress.steps).length,0);assert.equal(e.c.JPWModuleAvailability.canAccess('alladin'),false);});
test('Dante unavailable Forex advances to editorial PF chapter even if PF is also frozen',()=>{for(const action of ['next','skip']){const e=env(),c=e.c.JPWLearningCatalog;e.c.JPWModuleAvailability.canAccess=id=>!['forex','personal-finance'].includes(id);e.c.JPWLearningGuide.startJourney({stepId:'forex-accounts'});e.flush();assert.equal(e.c.model.unavailable,true);e.c.cb[action]();e.flush();assert.equal(e.c.JPWLearningGuide.snapshot().stepId,c.journey.find(x=>x.id==='personal-finance').stepIds[0]);assert.equal(e.c.JPWLearningGuide.snapshot().trackId,'personal-finance');assert.equal(e.c.model.unavailable,true);assert.equal(Object.keys(e.c.JPWLearningGuide.snapshot().progress.steps).length,0);assert.equal(e.c.JPWNavigation.current().canonical,'dashboard');e.c.cb.back();e.flush();assert.equal(Object.keys(e.c.JPWLearningGuide.snapshot().progress.steps).length,0);}});
test('Dante presentation end reports separate outcomes without declaring all lessons completed',()=>{const e=env(),c=e.c.JPWLearningCatalog,last=c.journey.at(-1).stepIds.at(-1);e.c.JPWLearningGuide.startJourney({stepId:'basics-home'});e.flush();e.c.cb.skip();e.flush();e.c.JPWLearningGuide.startJourney({stepId:last});e.flush();e.c.cb.skip();e.flush();const s=e.c.JPWLearningGuide.snapshot();assert.equal(s.paused,true);assert.ok(s.notice.startsWith('Apresentação encerrada.'));assert.ok(s.notice.includes('0 leituras ou ações observadas'));assert.ok(s.notice.includes('2 puladas'));assert.ok(s.notice.includes('0 práticas confirmadas'));assert.ok(s.notice.includes('sem registro'));assert.ok(!/conclu[ií]d/i.test(s.notice));});
// Retired identity remains a storage record, never a visible lesson or earned credit.
for(const schemaVersion of [1,2])for(const mode of ['track','journey'])test('retired Nocuda bookmark '+schemaVersion+'/'+mode+' is read without boot write and resumes Stoikus without credit',()=>{
 const old={schemaVersion,catalogVersion:1,trackId:'tools',stepId:'tools-nocuda',paused:true,steps:{'tools-nocuda':{orientation:'seen',practice:null}}};if(schemaVersion===2)old.mode=mode;
 const raw=JSON.stringify(old),e=env(raw),finance=e.data.get('jpwealth_v9_state');
 assert.equal(e.writes(),0);assert.equal(e.data.get('jpwealth_learning_guide_v1'),raw);
 const read=e.c.JPWLearningProgress.read(e.c.JPWLearningCatalog);assert.equal(read.ok,true);assert.equal(read.document.stepId,'tools-nocuda');assert.deepEqual(JSON.parse(JSON.stringify(read.document.steps)),old.steps);
 assert(!e.c.JPWLearningCatalog.tracks.flatMap(t=>t.steps).some(s=>s.id==='tools-nocuda'));assert(!e.c.JPWLearningCatalog.journey.flatMap(t=>t.stepIds).includes('tools-nocuda'));
 e.add('#tools');e.add('#toolsLeverage');e.c.JPWLearningGuide.resume();e.flush();
 assert.equal(e.c.JPWLearningGuide.snapshot().stepId,'tools-genetrix');assert.deepEqual(JSON.parse(JSON.stringify(e.c.JPWLearningGuide.snapshot().progress.steps)),old.steps);assert.equal(e.data.get('jpwealth_v9_state'),finance);
});
test('Dante v1 bookmark resumes legacy track mode without boot migration',()=>{const old={schemaVersion:1,catalogVersion:1,trackId:'basics',stepId:'basics-home',paused:true,steps:{}};const raw=JSON.stringify(old),e=env(raw);assert.equal(e.writes(),0);assert.equal(e.data.get('jpwealth_learning_guide_v1'),raw);e.add('#dash');e.c.JPWLearningGuide.resume();e.flush();assert.equal(e.c.JPWLearningGuide.snapshot().mode,'track');assert.equal(JSON.parse(e.data.get('jpwealth_learning_guide_v1')).schemaVersion,2);});
test('readiness never credits orientation until explicit acknowledgment',()=>{const e=setup();assert.equal(e.c.JPWLearningGuide.snapshot().progress.steps['basics-home'],undefined);e.c.cb.understand();assert.equal(e.c.JPWLearningGuide.snapshot().progress.steps['basics-home'].orientation,'seen');});
test('read acknowledgment and skip never claim practice',()=>{const e=setup();e.c.cb.understand();e.c.cb.skip();const records=e.c.JPWLearningGuide.snapshot().progress.steps;assert.equal(records['basics-home'].practice,null);assert.ok(Object.values(records).some(s=>s.orientation==='skipped'));});
test('snapshot is defensive and excludes live personal state',()=>{const e=setup();const s=e.c.JPWLearningGuide.snapshot();s.progress.steps.bad={orientation:'seen',practice:'confirmed'};assert.equal(e.c.JPWLearningGuide.snapshot().progress.steps.bad,undefined);assert.ok(!JSON.stringify(s).includes('personalFinance'));});
test('pause invalidates queued anchor work and resume rechecks live target',()=>{const e=setup();e.c.cb.pause();e.els.get('#dash').hidden=true;e.flush();assert.equal(e.c.JPWLearningGuide.snapshot().paused,true);e.c.JPWLearningGuide.resume();e.flush();assert.equal(e.c.JPWLearningGuide.snapshot().paused,true);});
test('foreign accepted route pauses without credit or navigation back',()=>{const e=setup();e.route({canonical:'tools-calendar',primary:'tools',screen:'tools',localView:{surface:'tools',view:'calendar'}});e.flush();assert.equal(e.c.JPWLearningGuide.snapshot().paused,true);assert.equal(e.c.JPWLearningGuide.snapshot().progress.steps['basics-home'],undefined);});
test('frozen Alladin pauses without changing availability',()=>{const e=setup('alladin');assert.equal(e.c.JPWLearningGuide.snapshot().paused,true);assert.equal(e.c.JPWModuleAvailability.canAccess('alladin'),false);});
test('incompatible bytes survive every action until explicit restart',()=>{const e=env('{future:true}');assert.ok(e.c.JPWLearningGuide);e.c.JPWLearningGuide.start('basics');e.flush();assert.equal(e.data.get('jpwealth_learning_guide_v1'),'{future:true}');assert.equal(e.writes(),0);e.c.JPWLearningGuide.restart();assert.notEqual(e.data.get('jpwealth_learning_guide_v1'),'{future:true}');});
test('refused guide storage stays honest in memory and preserves financial bytes',()=>{const e=env();e.refuse();e.add('#dash');e.add('#brandHomeBtn');e.c.JPWLearningGuide.start('basics');e.flush();e.c.cb.understand();assert.equal(e.c.JPWLearningGuide.snapshot().storage,'memory');assert.equal(e.data.get('jpwealth_v9_state'),'{"personalFinance":{"months":{}},"mvpNotes":{"items":[]}}');});
test('external progress change pauses/reloads without navigating',()=>{const e=setup();e.data.set('jpwealth_learning_guide_v1',null);e.emit('storage',{key:'jpwealth_learning_guide_v1'});e.flush();assert.equal(e.c.JPWLearningGuide.snapshot().paused,true);assert.equal(e.c.JPWNavigation.current().canonical,'dashboard');});
test('session disposal prevents stale callbacks writing reset progress',()=>{const e=setup();e.c.JPWLearningGuide.disposeForSession();e.data.delete('jpwealth_learning_guide_v1');const n=e.writes();e.flush();assert.equal(e.writes(),n);assert.equal(e.data.has('jpwealth_learning_guide_v1'),false);});
test('practice needs original targeted fresh confirmed scoped write',()=>{const e=setup('personal-finance');const track=e.c.JPWLearningCatalog.tracks.find(t=>t.id==='personal-finance');const ix=track.steps.findIndex(s=>s.practice==='budget');for(let i=0;i<ix;i++)e.c.cb.skip();e.add('#finpesBudgetRoot');const field=e.add('[data-fi-campo],[data-fe-campo]');field.dataset={fiCampo:'name',fiId:'r1'};field.value='Minha receita';e.data.set('jpwealth_v9_state',JSON.stringify({personalFinance:{months:{'2026-10':{incomes:[{id:'r1',name:'Antes'}]}}}}));e.c.cb.go();e.flush();let apply=false;field.addEventListener('change',()=>{if(apply){e.data.set('jpwealth_v9_state',JSON.stringify({personalFinance:{months:{'2026-10':{incomes:[{id:'r1',name:'Minha receita'}]}}}}));e.setLast({status:'CONFIRMED',reason:'READBACK_MATCH',context:'ctx',epoch:1,at:'newer'});}});e.c.cb.practice();e.flush();field.emit('change');e.flush();assert.notEqual(e.c.JPWLearningGuide.snapshot().progress.steps[track.steps[ix].id]?.practice,'confirmed');e.setLast({status:'CONFIRMED',reason:'READBACK_MATCH',context:'ctx',epoch:1,at:'fresh'});apply=true;field.emit('change');e.data.set('jpwealth_v9_state',JSON.stringify({personalFinance:{months:{'2026-10':{incomes:[{id:'r1',name:'Minha receita'}]}}}}));e.setLast({status:'CONFIRMED',reason:'READBACK_MATCH',context:'ctx',epoch:1,at:'newer'});e.flush();assert.equal(e.c.JPWLearningGuide.snapshot().progress.steps[track.steps[ix].id].practice,'confirmed');});
test('desktop navigation remains readable when compact toggle is hidden',()=>{const e=setup();e.add('[data-shell-menu-toggle]').hidden=true;e.add('[data-route="dashboard"]');e.c.cb.skip();e.flush();assert.equal(e.c.JPWLearningGuide.snapshot().paused,false);});
