test('native checklist exit restores reachable coach in original Settings owner',()=>{const e=env();const track=e.c.JPWLearningCatalog.tracks.find(t=>t.id==='general');const ix=track.steps.findIndex(s=>s.destination?.settings==='tool-check');const dialog=e.add('#forexChecklistDialog');dialog.open=true;e.add('#checkWidgetGrid');const close=e.add('#forexChecklistClose');const title=e.add('#settingsPageTitle');e.c.JPWLearningGuide.start('general');e.flush();for(let n=0;n<ix;n++)e.c.cb.skip();e.flush();e.c.JPWLearningView.selectHost=target=>({host:e.c.document.body,foreign:dialog.open&&target!==close});e.c.cb.skip();e.flush();assert.equal(e.c.model.anchor,close);dialog.open=false;close.hidden=true;e.mutate();e.flush();assert.equal(e.c.model.status,'paused');assert.equal(e.c.model.anchor,title);});
test('beginner basics covers welcome choices, breadcrumb and financial local persistence modes',()=>{const e=env();const t=e.c.JPWLearningCatalog.tracks.find(t=>t.id==='basics');const text=t.steps.map(s=>s.instruction).join(' ');for(const term of ['Começar do zero','Restaurar Backup Completo','Conhecer com Dante','origem','rascunho','salva ao sair'])assert.ok(text.includes(term),term);assert.ok(t.steps.some(s=>s.anchor==='#shellLocation'));});
