test('native controller Next retains guide-owned keyboard focus across teardown',()=>{const e=uiEnv();e.add('dash');const menu=e.add('menu','button');menu.dataset.route='dashboard';e.c.JPWLearningGuide.start('basics');e.flush();let count=0;while(!e.c.JPWLearningGuide.snapshot().progress.steps['basics-home']&&count++<30)e.doc.getElementById('jpwLearningUnderstand').emit('click');assert.ok(count<30);const next=e.doc.getElementById('jpwLearningNext');assert.equal(next.hidden,false);assert.equal(next.disabled,false);next.focus();next.emit('click');e.flush();assert.ok(e.doc.activeElement.closest('#jpwLearningCoach'),'focus remains in successful new coach');assert.notEqual(e.doc.activeElement,e.doc.body);});
test('view never restores guide focus over a real typing input or new native dialog host',()=>{const e=uiEnv();const anchor=e.add('anchor','button');const actions={go(){},understand(){},back(){},next(){},skip(){},pause(){}};const step={id:'x',title:'t',objective:'o',instruction:'i',expected:'e',kind:'read',destination:{route:'dashboard'}};const model={step,anchor,status:'waiting',index:0,last:false,count:'1',notice:'x',done:true};e.c.JPWLearningView.coach(model,actions);e.doc.getElementById('jpwLearningNext').focus();e.c.JPWLearningView.hide({preserveFocus:true});const input=e.add('input','input');input.focus();e.c.JPWLearningView.coach(model,actions);assert.equal(e.doc.activeElement,input);e.doc.getElementById('jpwLearningNext').focus();e.c.JPWLearningView.hide({preserveFocus:true});const dialog=e.add('native','dialog');dialog.open=true;const field=e.add('field','input');dialog.append(field);field.focus();e.c.JPWLearningView.coach({...model,anchor:field},actions);assert.equal(e.doc.activeElement,field);});
test('nested scroll repositions actual view and capture listener is removed on hide',()=>{const e=uiEnv();const anchor=e.add('anchor','button');anchor.rect={left:100,top:280,right:200,bottom:320,width:100,height:40};const actions={go(){},understand(){},back(){},next(){},skip(){},pause(){}};e.c.JPWLearningView.coach({step:{id:'x',title:'t',objective:'o',instruction:'i',expected:'e',kind:'read'},anchor,status:'waiting',index:0,last:false,count:'1',notice:'x',done:false},actions);e.flush();const coach=e.doc.getElementById('jpwLearningCoach');assert.equal(coach.style.top,'280px');anchor.rect={...anchor.rect,top:180,bottom:220};e.nestedScroll(anchor);e.flush();assert.equal(coach.style.top,'180px');e.c.JPWLearningView.hide();assert.equal(e.listeners('scroll').length,0);});

