for(const command of ['skip','next','back','start','go','understand','resume'])test('unknown divergent readback aborts entire '+command+' command',()=>{
 const e=setup();e.add('[data-shell-menu-toggle]');e.add('#shellLocation');if(command==='next')e.c.cb.understand();if(command==='back'){e.c.cb.skip();e.flush();}if(command==='go'){e.route({canonical:'tools-normative',primary:'tools',screen:'tools',localView:{surface:'tools',view:'normative'}});e.flush();}const competing=conflictDocument(e),route=e.c.JPWNavigation.current().canonical;const financial=e.data.get('jpwealth_v9_state');let attempted=0;e.c.localStorage.setItem=(key,value)=>{attempted++;e.data.set(key,key==='jpwealth_learning_guide_v1'?competing:value);};if(command==='start')e.c.JPWLearningGuide.start('personal-finance');else if(command==='resume')e.c.JPWLearningGuide.resume();else e.c.cb[command]();e.flush();assert.equal(attempted,1,'single ambiguous attempt, no continuation/retry');assert.equal(e.data.get('jpwealth_learning_guide_v1'),competing);assert.equal(e.c.JPWNavigation.current().canonical,route);assert.equal(e.data.get('jpwealth_v9_state'),financial);assert.equal(e.c.JPWLearningGuide.snapshot().paused,true);
});
