function speechView(reduced=false){const e=uiEnv(),timers=new Map();let id=0;e.c.matchMedia=()=>({matches:reduced});e.c.setTimeout=(fn,delay)=>{timers.set(++id,{fn,delay});return id;};e.c.clearTimeout=id=>timers.delete(id);return {...e,timers,tick(){const one=timers.entries().next().value;if(one){timers.delete(one[0]);one[1].fn();}}};}
function speechModel(e,overrides={}){return {step:{id:'speech',title:'Dante',objective:'Objetivo completo.',instruction:'Instrução completa.',expected:'Resultado completo.',kind:'read'},anchor:null,status:'waiting',index:0,last:false,count:'1',notice:'Leia.',done:false,speech:'Olá, vamos conhecer o app.',speechKey:'speech:0',speechIndex:0,speechTotal:2,...overrides};}
