test('Dante unavailable narration keeps Next visible for reveal then next editorial chapter',()=>{const e=speechView(),c=e.c.JPWLearningCatalog,id=c.journey.find(x=>x.id==='alladin').stepIds[0];e.c.JPWLearningGuide.startJourney({stepId:id});e.flush();let next=e.doc.getElementById('jpwLearningNext');assert.equal(next.hidden,false);assert.equal(next.disabled,false);const writes=e.writes();next.emit('click');assert.equal(e.c.JPWLearningGuide.snapshot().stepId,id);assert.ok(e.doc.getElementById('jpwLearningSpeech').textContent.length>0);assert.equal(e.writes(),writes);next=e.doc.getElementById('jpwLearningNext');assert.equal(next.hidden,false);next.emit('click');e.flush();assert.equal(e.c.JPWLearningGuide.snapshot().stepId,c.journey.find(x=>x.id==='general').stepIds[0]);assert.equal(Object.keys(e.c.JPWLearningGuide.snapshot().progress.steps).length,0);});
// Synthetic DOM lifecycle exercises real catalog selector strings without parsing CSS lists.
function followFixture(id){const e=speechView(),step=e.c.JPWLearningCatalog.tracks.flatMap(t=>t.steps).find(s=>s.id===id),aliases=new Map(),qs=e.doc.querySelector,qsa=e.doc.querySelectorAll;assert.ok(step.followHosts?.length);assert.ok(step.speechAnchors?.length);e.doc.querySelector=selector=>aliases.get(selector)||qs(selector);e.doc.querySelectorAll=selector=>aliases.has(selector)?[aliases.get(selector)]:qsa(selector);const entry=e.add(id.startsWith('planning')?'planning':'execEcal');aliases.set(step.speechAnchors[0],entry);e.c.JPWLearningGuide.startJourney({stepId:id});e.flush();const dialog=e.add('originalOwnedDialog','dialog');dialog.open=true;aliases.set(step.followHosts[id==='planning-form'?1:0],dialog);const input=e.add('originalTypedField','input');input.value='rascunho próprio';dialog.append(input);input.focus();e.mutate();e.flush();return {...e,lesson:step,aliases,dialog,input,advanceTo(index){for(let i=e.c.model?.speechIndex||0;i<index;i++){const button=e.doc.getElementById('jpwLearningUnderstand');button.emit('click');e.doc.getElementById('jpwLearningUnderstand').emit('click');}}};}
for(const id of ['planning-form','planning-monthly','tools-agenda'])test('Dante follows allowed '+id+' dialog with untouched typed draft and no financial write',()=>{const e=followFixture(id),financial=e.data.get('jpwealth_v9_state');assert.equal(e.c.JPWLearningGuide.snapshot().paused,false);assert.equal(e.doc.getElementById('jpwLearningCoach').parentElement,e.dialog);assert.equal(e.doc.activeElement,e.input);const field=e.add('currentSpeechField','input');field.value='prévia preservada';e.dialog.append(field);e.aliases.set(e.lesson.speechAnchors[1],field);e.advanceTo(1);assert.equal(field.getAttribute('aria-describedby'),'jpwLearningExpected');assert.equal(e.doc.activeElement,e.input);let navigations=0;e.c.JPWNavigation.navigateLocal=()=>{navigations++;return true;};e.c.JPWNavigation.navigate=()=>{navigations++;return true;};e.c.JPWLearningGuide.pause();e.c.JPWLearningGuide.resume();e.flush();e.doc.getElementById('jpwLearningGo').emit('click');e.flush();assert.equal(navigations,0);assert.equal(e.input.value,'rascunho próprio');assert.equal(field.value,'prévia preservada');assert.equal(e.dialog.open,true);assert.equal(e.data.get('jpwealth_v9_state'),financial);assert.equal(e.c.JPWLearningGuide.snapshot().progress.steps[id],undefined);});
test('Dante allowed dialog review/cancel and Agenda field replacement preserve ownership',()=>{for(const id of ['planning-form','planning-monthly','tools-agenda']){const e=followFixture(id),financial=e.data.get('jpwealth_v9_state'),current=e.add('oldField','input');e.dialog.append(current);e.aliases.set(e.lesson.speechAnchors[1],current);e.advanceTo(1);e.doc.getElementById('jpwLearningUnderstand').emit('click');const before=e.doc.getElementById('jpwLearningSpeech').textContent;current.remove();const replacement=e.add('replacementKindOrReview','input');replacement.value=id==='tools-agenda'?'appointment/allDay=false':'revisão sem confirmar';e.dialog.append(replacement);e.aliases.set(e.lesson.speechAnchors[1],replacement);replacement.focus();e.mutate();e.flush();assert.equal(e.doc.getElementById('jpwLearningSpeech').textContent,before);assert.equal(e.doc.activeElement,replacement);assert.equal(replacement.getAttribute('aria-describedby'),'jpwLearningExpected');e.dialog.open=false;e.dialog.hidden=true;e.mutate();e.flush();assert.equal(e.c.JPWLearningGuide.snapshot().paused,false);assert.equal(e.dialog.hidden,true);assert.equal(e.data.get('jpwealth_v9_state'),financial);assert.equal(e.c.JPWLearningGuide.snapshot().progress.steps[id],undefined);}});
test('Dante cannot leave an owned draft lesson or adopt a foreign dialog',()=>{const e=followFixture('planning-form'),id=e.c.JPWLearningGuide.snapshot().stepId;e.c.JPWLearningGuide.startJourney({stepId:'planning-monthly'});e.flush();assert.equal(e.c.JPWLearningGuide.snapshot().stepId,id);assert.equal(e.c.JPWLearningGuide.snapshot().paused,true);assert.equal(e.dialog.open,true);assert.equal(e.input.value,'rascunho próprio');e.c.JPWLearningGuide.resume();e.flush();const foreign=e.add('unrelatedNativeDialog','dialog');foreign.open=true;e.mutate();e.flush();assert.equal(e.c.JPWLearningGuide.snapshot().paused,true);assert.equal(e.c.JPWLearningGuide.snapshot().progress.steps[id],undefined);});
test('Dante follows an allowed sibling profile/stop modal and rejects a destructive sibling',()=>{const e=followFixture('planning-form'),sub=e.add('nativeComparisonModal','dialog');sub.open=true;e.aliases.set(e.lesson.followHosts[3],sub);const choice=e.add('nativeProfileChoice','button');sub.append(choice);choice.focus();e.mutate();e.flush();assert.equal(e.c.JPWLearningGuide.snapshot().paused,false);assert.equal(e.doc.getElementById('jpwLearningCoach').parentElement,sub);assert.equal(e.doc.activeElement,choice);assert.equal(e.dialog.open,true);const destructive=e.add('nativeArchiveDialog','dialog');destructive.open=true;e.mutate();e.flush();assert.equal(e.c.JPWLearningGuide.snapshot().paused,true);assert.equal(e.c.JPWLearningGuide.snapshot().progress.steps['planning-form'],undefined);});
test('Dante reserves normal flow outside an editable logical form and releases it after cancellation',()=>{const e=speechView(),region=e.add('nativeFormRegion'),form=e.add('nativeAgendaForm','form'),field=e.add('nativeAgendaTitle','input');region.append(form);form.append(field);field.value='rascunho sem salvar';field.focus();const model=speechModel(e,{anchor:field,followingHost:true,followRoot:form});e.c.JPWLearningView.coach(model,viewActions());let card=e.doc.getElementById('jpwLearningCoach');assert.equal(card.parentElement,region);assert.equal(card.dataset.learningLayout,'flow');assert.equal(card.style.position,'static');assert.equal(form.contains(card),false);assert.ok(region.children.indexOf(card)<region.children.indexOf(form));assert.equal(e.doc.activeElement,field);e.tick();const before=e.doc.getElementById('jpwLearningSpeech').textContent;form.remove();const entry=e.add('nativeCalendarEntry');e.c.JPWLearningView.coach({...model,anchor:entry,followingHost:false,followRoot:null},viewActions());card=e.doc.getElementById('jpwLearningCoach');assert.equal(card.parentElement,e.doc.body);assert.equal(e.doc.getElementById('jpwLearningSpeech').textContent,before);assert.equal(field.value,'rascunho sem salvar');});
test('Dante opening the center removes a suspended coach and invalidates queued exit redraws',()=>{const e=env(),track=e.c.JPWLearningCatalog.tracks.find(t=>t.id==='general'),ix=track.steps.findIndex(s=>s.destination?.settings==='tool-check'),dialog=e.add('#forexChecklistDialog');dialog.open=true;e.add('#checkWidgetGrid');const close=e.add('#forexChecklistClose');e.add('#settingsPageTitle');e.c.JPWLearningGuide.start('general');e.flush();for(let n=0;n<ix;n++)e.c.cb.skip();e.flush();e.c.JPWLearningView.selectHost=target=>({host:e.c.document.body,foreign:dialog.open&&target!==close});e.c.cb.skip();e.flush();dialog.open=false;close.hidden=true;e.mutate();e.flush();assert.equal(e.c.model.status,'paused');const before=e.c.JPWLearningGuide.snapshot(),financial=e.data.get('jpwealth_v9_state');assert.equal(e.c.JPWLearningGuide.open(),true);assert.equal(e.c.model,null);e.mutate();e.flush();assert.equal(e.c.model,null);assert.equal(e.c.JPWLearningGuide.snapshot().stepId,before.stepId);assert.equal(e.c.JPWLearningGuide.snapshot().paused,true);assert.equal(e.data.get('jpwealth_v9_state'),financial);});
test('Dante center takes its own surface without an overlapping paused card',()=>{const e=speechView();e.add('dash');e.c.JPWLearningGuide.startJourney();e.flush();e.route({canonical:'tools-calendar',primary:'tools',screen:'tools',localView:null});e.flush();assert.equal(e.c.JPWLearningGuide.snapshot().paused,true);assert.ok(e.doc.getElementById('jpwLearningCoach'));const financial=e.data.get('jpwealth_v9_state');e.c.openSettingsModal=()=>{const panel=e.add('nativeLearningPanel');panel.dataset.settingsPanel='learning-guide';};assert.equal(e.c.JPWLearningGuide.open(),true);assert.equal(e.doc.getElementById('jpwLearningCoach'),null);assert.ok(e.doc.getElementById('jpwLearningResume'));assert.equal(e.doc.getElementById('jpwLearningResume').disabled,false);assert.equal(e.data.get('jpwealth_v9_state'),financial);});
test('Dante reduced motion and resumed speech are complete without timer or focus change',()=>{for(const reduced of [true,false]){const e=speechView(reduced),model=speechModel(e,{speechFull:!reduced});e.c.JPWLearningView.coach(model,viewActions());assert.equal(e.doc.getElementById('jpwLearningSpeech').textContent,model.speech);assert.equal(e.timers.size,0);assert.equal(e.doc.activeElement,e.doc.body);}});
test('Dante actual controller reveal and speech changes never mark reading before final acknowledgment',()=>{const e=speechView();e.add('dash');e.c.JPWLearningGuide.startJourney();e.flush();const id=e.c.JPWLearningGuide.snapshot().stepId,writes=e.writes(),lines=e.c.JPWLearningCatalog.tracks[0].steps[0].speech;const click=()=>e.doc.getElementById('jpwLearningUnderstand').emit('click');click();assert.equal(e.writes(),writes);assert.equal(e.c.JPWLearningGuide.snapshot().progress.steps[id],undefined);for(let i=1;i<lines.length;i++){click();assert.equal(e.doc.getElementById('jpwLearningSpeechAccessible').textContent,lines[i]);assert.equal(e.c.JPWLearningGuide.snapshot().progress.steps[id],undefined);click();}click();assert.deepEqual(JSON.parse(JSON.stringify(e.c.JPWLearningGuide.snapshot().progress.steps[id])),{orientation:'seen',practice:null});assert.equal(e.c.JPWLearningGuide.snapshot().stepId,id);assert.ok(!Object.hasOwn(JSON.parse(e.data.get('jpwealth_learning_guide_v1')),'speechIndex'));});
test('Dante action narration exposes reveal while original action remains required',()=>{const e=speechView(),menu=e.add('homeMenu','button');menu.dataset.route='dashboard';e.c.JPWLearningGuide.startJourney({stepId:'basics-menu'});e.flush();let n=0;while(n++<20){const b=e.doc.getElementById('jpwLearningUnderstand');if(b.disabled)break;assert.equal(b.hidden,false);b.emit('click');}assert.ok(n<20);assert.equal(e.c.JPWLearningGuide.snapshot().progress.steps['basics-menu'],undefined);assert.equal(e.doc.getElementById('jpwLearningNext').disabled,true);});
test('Dante pause cancels typing and resumes same speech whole; reload returns to its first speech',()=>{const e=speechView();e.add('dash');e.c.JPWLearningGuide.startJourney();e.flush();e.doc.getElementById('jpwLearningUnderstand').emit('click');e.doc.getElementById('jpwLearningUnderstand').emit('click');const current=e.doc.getElementById('jpwLearningSpeechAccessible').textContent;assert.ok(e.timers.size);const stale=[...e.timers.values()][0].fn;e.c.JPWLearningGuide.pause();assert.equal(e.timers.size,0);stale();assert.equal(e.doc.getElementById('jpwLearningCoach'),null);e.c.JPWLearningGuide.resume();e.flush();assert.equal(e.doc.getElementById('jpwLearningSpeech').textContent,current);assert.equal(e.timers.size,0);const raw=e.data.get('jpwealth_learning_guide_v1'),loaded=env(raw);loaded.add('#dash');loaded.c.JPWLearningGuide.resume();loaded.flush();assert.equal(loaded.c.model.speechIndex,0);});
test('Dante visibility and session disposal leave no scheduled narration',()=>{for(const dispose of [false,true]){const e=speechView();e.add('dash');e.c.JPWLearningGuide.startJourney();e.flush();assert.ok(e.timers.size);if(dispose)e.c.JPWLearningGuide.disposeForSession();else{e.c.document.hidden=true;e.emitDocument('visibilitychange');assert.equal(e.c.JPWLearningGuide.snapshot().paused,true);}assert.equal(e.timers.size,0);}});
